import 'dart:async';

import 'package:flutter/foundation.dart';
import 'package:xterm2/xterm.dart';

/// Finds literal text in the active terminal buffer, including scrollback.
///
/// xterm owns cell mapping for wide characters, combining marks and wrapped
/// lines. Its anchored highlights follow reflow and are scoped to their buffer.
/// Rescans are throttled during output, and navigation always refreshes dirty
/// results before using them. No terminal input is generated by a search.
class TerminalScrollbackSearch extends ChangeNotifier {
  TerminalScrollbackSearch({
    required this.terminal,
    required this.controller,
    this.onReveal,
    this.refreshDelay = const Duration(milliseconds: 150),
  }) {
    terminal.addListener(_onTerminalChanged);
  }

  static const int maximumMatches = 1000;

  final Terminal terminal;
  final TerminalController controller;
  final VoidCallback? onReveal;
  final Duration refreshDelay;

  String _query = '';
  bool _caseSensitive = false;
  bool _wholeWord = false;
  bool _dirty = false;
  bool _resetCurrent = true;
  bool _disposed = false;
  bool _truncated = false;
  int _currentIndex = -1;
  int _revision = 0;
  List<TerminalSearchMatch> _matches = const [];
  Buffer? _searchedBuffer;
  CellAnchor? _preferredAnchor;
  Timer? _refreshTimer;
  Timer? _invalidationTimer;

  String get query => _query;
  bool get caseSensitive => _caseSensitive;
  bool get wholeWord => _wholeWord;
  bool get pending => _dirty && _query.isNotEmpty;
  bool get truncated => _truncated;
  int get matchCount => _matches.length;
  int get currentIndex => _currentIndex;

  /// Changes whenever old coordinates must no longer be used by the viewport.
  int get revision => _revision;

  BufferRangeLine? get currentRange {
    if (_dirty ||
        _currentIndex < 0 ||
        _currentIndex >= controller.searchHighlights.length) {
      return null;
    }
    return controller.searchHighlights[_currentIndex].rangeFor(terminal.buffer);
  }

  void setQuery(String value) {
    if (_query == value || _disposed) return;
    _query = value;
    _criteriaChanged();
  }

  void setCaseSensitive(bool value) {
    if (_caseSensitive == value || _disposed) return;
    _caseSensitive = value;
    _criteriaChanged();
  }

  void setWholeWord(bool value) {
    if (_wholeWord == value || _disposed) return;
    _wholeWord = value;
    _criteriaChanged();
  }

  void _criteriaChanged() {
    _revision++;
    _resetCurrent = true;
    _releasePreferredAnchor();
    _currentIndex = -1;
    _matches = const [];
    _truncated = false;
    _dirty = _query.isNotEmpty;
    _refreshTimer?.cancel();
    _refreshTimer = null;
    _invalidationTimer?.cancel();
    _invalidationTimer = null;
    controller.clearSearchHighlights();
    notifyListeners();
    _scheduleRefresh();
  }

  void _onTerminalChanged() {
    if (_disposed || _query.isEmpty) return;
    _revision++;
    if (!_dirty && identical(_searchedBuffer, terminal.buffer)) {
      final range = currentRange;
      if (range != null) {
        _preferredAnchor = terminal.buffer.createAnchorFromOffset(range.begin);
      }
    }
    if (!identical(_searchedBuffer, terminal.buffer)) {
      _releasePreferredAnchor();
      _resetCurrent = true;
    }
    _dirty = true;
    // Terminal resizing can notify during Flutter layout. Defer controller
    // and widget notifications to the next event turn to avoid a build-time
    // setState, while invalidating coordinates synchronously above.
    _invalidationTimer ??= Timer(Duration.zero, () {
      _invalidationTimer = null;
      if (_disposed || !_dirty) return;
      controller.clearSearchHighlights();
      notifyListeners();
    });
    _scheduleRefresh();
  }

  void _scheduleRefresh() {
    if (_disposed || _query.isEmpty || _refreshTimer != null) return;
    // Do not restart this timer for every output chunk: a busy terminal still
    // gets fresh results at bounded intervals instead of starving the search.
    _refreshTimer = Timer(refreshDelay, refresh);
  }

  /// Refreshes the active buffer now. Exposed for explicit navigation/testing.
  void refresh() {
    if (_disposed) return;
    _refreshTimer?.cancel();
    _refreshTimer = null;
    _invalidationTimer?.cancel();
    _invalidationTimer = null;
    if (!_dirty) return;

    final reveal = _resetCurrent;
    final preferred = _preferredAnchor;
    final start = preferred != null && terminal.buffer.ownsAnchor(preferred)
        ? preferred.offset
        : null;
    final found = terminal.search(
      _query,
      caseSensitive: _caseSensitive,
      wholeWord: _wholeWord,
      // Literal search avoids user-controlled regex backtracking in the UI
      // isolate. Read one extra result to distinguish "1000" from "1000+".
      maxResults: maximumMatches + 1,
    );
    _truncated = found.length > maximumMatches;
    _matches = found.take(maximumMatches).toList(growable: false);
    _currentIndex = _matches.isEmpty ? -1 : 0;
    if (_matches.isNotEmpty && !_resetCurrent && start != null) {
      final atOrAfter = _matches.indexWhere(
        (match) => match.range.begin.isAfterOrSame(start),
      );
      _currentIndex = atOrAfter < 0 ? _matches.length - 1 : atOrAfter;
    }
    _searchedBuffer = terminal.buffer;
    _dirty = false;
    _resetCurrent = false;
    _releasePreferredAnchor();
    controller.setSearchHighlights(
      terminal.buffer,
      _matches.map((match) => match.range).toList(growable: false),
      currentIndex: _currentIndex,
    );
    notifyListeners();
    // Background output updates highlights but never drag the user's viewport.
    if (reveal && _currentIndex >= 0) onReveal?.call();
  }

  void next() => _move(1);
  void previous() => _move(-1);

  void _releasePreferredAnchor() {
    _preferredAnchor?.dispose();
    _preferredAnchor = null;
  }

  void _move(int direction) {
    if (_disposed) return;
    final hadCurrent = _currentIndex >= 0 && !_resetCurrent;
    refresh();
    if (_matches.isEmpty) return;
    if (hadCurrent) {
      _currentIndex = (_currentIndex + direction) % _matches.length;
    } else if (direction < 0) {
      _currentIndex = _matches.length - 1;
    }
    controller.setCurrentSearchHighlight(_currentIndex);
    notifyListeners();
    onReveal?.call();
  }

  @override
  void dispose() {
    if (_disposed) return;
    _disposed = true;
    _refreshTimer?.cancel();
    _invalidationTimer?.cancel();
    _releasePreferredAnchor();
    terminal.removeListener(_onTerminalChanged);
    controller.clearSearchHighlights();
    super.dispose();
  }
}
